"""Pose math and the body model used for calibration.

Poses are (pos: np.array(3), rot: np.array(4) as w x y z) in SteamVR's standing space
(floor at y=0, +Y up, -Z forward, +X right).
"""
import numpy as np

UP = np.array([0.0, 1.0, 0.0])

# Body model, relative to the head at T-pose time. Heights are fractions of eye height.
# The head turns around the neck, not the eyes: looking down moves the eyes ~8 cm forward
# and down. Everything hangs from this pivot so nodding does not move the body (2026-10-23).
NECK_UP = 0.11          # eyes sit this far above the neck pivot (m)
NECK_FWD = 0.08         # ... and this far in front of it, on the spine axis (m)
WAIST_HEIGHT = 0.56     # × eye height
ANKLE_HEIGHT = 0.048    # × eye height
ANKLE_SIDE = 0.06       # half-distance between ankle centres in pencil pose (m)

ROLES = ("waist", "left_foot", "right_foot")

# A tracker this close to the eyes rides on the headset (e.g. Space Calibrator's reference
# for a Quest + Lighthouse mix, 2026-10-28) — it is not a body tracker. The waist sits
# ~0.6 m below the eyes in a T-pose, so this cannot catch a real one.
HEAD_MOUNT_RADIUS = 0.30


def q_mul(a, b):
    aw, ax, ay, az = a
    bw, bx, by, bz = b
    return np.array([
        aw * bw - ax * bx - ay * by - az * bz,
        aw * bx + ax * bw + ay * bz - az * by,
        aw * by - ax * bz + ay * bw + az * bx,
        aw * bz + ax * by - ay * bx + az * bw,
    ])


def q_conj(q):
    return np.array([q[0], -q[1], -q[2], -q[3]])


def q_rot(q, v):
    qv = np.array([0.0, *v])
    return q_mul(q_mul(q, qv), q_conj(q))[1:]


def q_norm(q):
    return q / np.linalg.norm(q)


def q_yaw(forward):
    """Rotation whose -Z points along the horizontal `forward` direction."""
    yaw = np.arctan2(-forward[0], -forward[2])
    return np.array([np.cos(yaw / 2), 0.0, np.sin(yaw / 2), 0.0])


def mat_to_pose(m):
    """HmdMatrix34 (3x4 nested list/array) -> (pos, quat)."""
    m = np.asarray(m, dtype=float)
    r = m[:, :3]
    t = m[:, 3].copy()
    tr = r[0, 0] + r[1, 1] + r[2, 2]
    if tr > 0:
        s = np.sqrt(tr + 1.0) * 2
        q = [0.25 * s, (r[2, 1] - r[1, 2]) / s, (r[0, 2] - r[2, 0]) / s, (r[1, 0] - r[0, 1]) / s]
    elif r[0, 0] > r[1, 1] and r[0, 0] > r[2, 2]:
        s = np.sqrt(1.0 + r[0, 0] - r[1, 1] - r[2, 2]) * 2
        q = [(r[2, 1] - r[1, 2]) / s, 0.25 * s, (r[0, 1] + r[1, 0]) / s, (r[0, 2] + r[2, 0]) / s]
    elif r[1, 1] > r[2, 2]:
        s = np.sqrt(1.0 + r[1, 1] - r[0, 0] - r[2, 2]) * 2
        q = [(r[0, 2] - r[2, 0]) / s, (r[0, 1] + r[1, 0]) / s, 0.25 * s, (r[1, 2] + r[2, 1]) / s]
    else:
        s = np.sqrt(1.0 + r[2, 2] - r[0, 0] - r[1, 1]) * 2
        q = [(r[1, 0] - r[0, 1]) / s, (r[0, 2] + r[2, 0]) / s, (r[1, 2] + r[2, 1]) / s, 0.25 * s]
    return t, q_norm(np.array(q))


def pose_to_mat(pos, q):
    w, x, y, z = q
    r = np.array([
        [1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)],
        [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)],
        [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)],
    ])
    return np.hstack([r, np.asarray(pos, dtype=float).reshape(3, 1)])


def compose(a, b):
    """a * b for poses."""
    return a[0] + q_rot(a[1], b[0]), q_norm(q_mul(a[1], b[1]))


def inverse(a):
    qi = q_conj(a[1])
    return -q_rot(qi, a[0]), qi


def head_frame(head):
    """Horizontal forward/right unit vectors from a head pose.

    Uses only the yaw part of the rotation (swing-twist about +Y), so looking straight
    down or up keeps a steady forward instead of flipping.
    """
    w, _, y, _ = head[1]
    n = np.hypot(w, y)
    yaw = np.array([w / n, 0.0, y / n, 0.0]) if n > 1e-6 else np.array([1.0, 0, 0, 0])
    fwd = q_rot(yaw, [0.0, 0.0, -1.0])
    right = np.cross(fwd, UP)
    return fwd, right


def neck(head):
    """Neck pivot: the point the head turns around (head-local +Z is backwards)."""
    return head[0] + q_rot(head[1], [0.0, -NECK_UP, NECK_FWD])


def level_eye_y(head):
    """Eye height the head would have when looking straight ahead."""
    return float(neck(head)[1] + NECK_UP)


def model_points(head, eye_height, head_y=None, ankle_side=ANKLE_SIDE):
    """Ideal joint poses for a straight T-pose with feet together ("pencil pose").

    `eye_height` is the standing eye height from calibration. When `head_y` is given
    (any-pose VRChat calibration, pass `level_eye_y(head)`), heights are placed relative
    to the current head instead of the floor, the way VRChat hangs the T-posed avatar from the head.
    `ankle_side` sets how far apart the feet are placed (Standable's "stance").
    """
    fwd, right = head_frame(head)
    rot = q_yaw(fwd)
    base = neck(head)
    base[1] = 0.0
    lift = 0.0 if head_y is None else head_y - eye_height

    def at(side, height):
        p = base + side * right
        p[1] = height * eye_height + lift
        return p, rot.copy()

    return {
        "waist": at(0.0, WAIST_HEIGHT),
        "left_foot": at(-ankle_side, ANKLE_HEIGHT),
        "right_foot": at(ankle_side, ANKLE_HEIGHT),
    }


def body_trackers(head, trackers):
    """Drop trackers mounted on the headset."""
    return {s: p for s, p in trackers.items()
            if np.linalg.norm(p[0] - head[0]) > HEAD_MOUNT_RADIUS}


def assign_roles(head, trackers):
    """trackers: {serial: pose}. Highest = waist, the two lowest split left/right."""
    if len(trackers) < 3:
        return None
    _, right = head_frame(head)
    by_height = sorted(trackers, key=lambda s: trackers[s][0][1], reverse=True)
    waist = by_height[0]
    feet = by_height[-2:]
    feet.sort(key=lambda s: np.dot(trackers[s][0] - head[0], right))
    return {waist: "waist", feet[0]: "left_foot", feet[1]: "right_foot"}


def feet_together(trackers, roles, max_gap=0.30, max_dy=0.05):
    """Pencil-pose guard: feet close together and at the same height."""
    lf = next(s for s, r in roles.items() if r == "left_foot")
    rf = next(s for s, r in roles.items() if r == "right_foot")
    d = trackers[lf][0] - trackers[rf][0]
    return np.hypot(d[0], d[2]) < max_gap and abs(d[1]) < max_dy


def calibrate(head, trackers):
    """Returns {serial: {"role", "off": (pos, rot)}} and the eye height, or None."""
    trackers = body_trackers(head, trackers)
    roles = assign_roles(head, trackers)
    if roles is None:
        return None, None
    eye = level_eye_y(head)
    model = model_points(head, eye)
    result = {}
    for serial, role in roles.items():
        result[serial] = {"role": role, "off": compose(inverse(trackers[serial]), model[role])}
    return result, eye
